// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address migratorAddress) public {
        vm.assume(migratorAddress != address(0));
        address someToken = address(0x123);
        c.addReward(someToken);
        c.setMigrator(migratorAddress);
        assertTrue(c.migrator() == migratorAddress);
    }
}

